"""Native, bilingual portfolio explanations. These are recreations, not shipped UI."""
from html import escape

def t(zh,en,lang): return zh if lang=='zh' else en

def preview(slug,lang):
 if slug=='playbook':
  return f'''<div class="native-preview preview-playbook" aria-label="{t('合成规则概念图','Crafting rule concept',lang)}"><div class="preview-eyebrow">PLAYBOOK / {t('一条规则，两种视角','ONE RULE, TWO PERSPECTIVES',lang)}</div><div class="preview-rule"><div class="mini-node"><span class="line-icon gamepad" aria-hidden="true">✛</span><b>Gamepad</b><small>{t('必选输入','Required input',lang)}</small></div><span class="flow-symbol">+</span><div class="mini-node"><span class="line-icon battery" aria-hidden="true">▰</span><b>Battery</b><small>{t('必选输入','Required input',lang)}</small></div><span class="flow-symbol">→</span><div class="mini-node output-node"><span class="line-icon" aria-hidden="true">↗</span><b>{t('合成结果','Crafted item',lang)}</b><small>{t('属性随规则变化','Attributes follow rules',lang)}</small></div></div><div class="preview-branch"><span class="branch-line" aria-hidden="true"></span><span>＋ Super Charger</span><small>{t('可选输入 · 改变计算方式','Optional input · changes the calculation',lang)}</small></div><div class="preview-bottom"><span>STUDIO → APP</span><span>{t('配置 → 检查 → 确认','Configure → Check → Confirm',lang)}</span></div></div>'''
 if slug=='qingju':
  return f'''<div class="native-preview preview-qingju" aria-label="{t('骑行前中后的体验概念图','Before, during and after ride concept',lang)}"><div class="preview-eyebrow">QINGJU / {t('让成长发生在路上','GROWTH ALONG THE WAY',lang)}</div><div class="journey-line" aria-hidden="true"><i>01</i><span></span><i>02</i><span></span><i>03</i></div><div class="journey-preview-steps"><div><small>{t('骑行前','BEFORE',lang)}</small><b>{t('找到想去的地方','Find a place',lang)}</b><span>{t('兴趣与路线','Interests & routes',lang)}</span></div><div><small>{t('骑行中','DURING',lang)}</small><b>{t('留一点探索空间','Room to explore',lang)}</b><span>{t('沿途与停留','Places & pauses',lang)}</span></div><div><small>{t('骑行后','AFTER',lang)}</small><b>{t('留下值得回顾的事','Keep a memory',lang)}</b><span>{t('记录与奖励','Memories & rewards',lang)}</span></div></div><div class="preview-bottom"><span>{t('由用户旅程到设计机会','JOURNEY → DESIGN OPPORTUNITIES',lang)}</span><span>01—03</span></div></div>'''
 if slug=='smt':
  return f'''<div class="native-preview preview-smt" aria-label="{t('表格状态与组件结构概念图','Table states and component structure concept',lang)}"><div class="preview-eyebrow">SMT / TABLE · ACCOUNT POSITIONS</div><div class="mini-table"><div class="mini-table-head"><span>{t('业务单元','BUSINESS UNIT',lang)}</span><span>{t('状态','STATE',lang)}</span></div><div><span><i class="mini-check"></i>{t('账户上下文','Account context',lang)}</span><small>{t('默认','Default',lang)}</small></div><div class="selected"><span><i class="mini-check">✓</i>{t('持仓信息','Position information',lang)}</span><small>{t('选中','Selected',lang)}</small></div><div><span><i class="mini-check"></i>{t('明确操作','Defined actions',lang)}</span><small>{t('悬停 / 聚焦','Hover / Focus',lang)}</small></div></div><div class="preview-bottom"><span>{t('固定结构，清晰反馈','STABLE STRUCTURE, CLEAR FEEDBACK',lang)}</span><span>DAY / NIGHT</span></div></div>'''
 return ''

def shell(kind,title,desc,body,lang,anchor='interactive-demo'):
 return f'''<div class="native-demo demo-{kind}" id="{anchor}" data-demo="{kind}"><header class="demo-header"><span class="demo-eyebrow"><i aria-hidden="true"></i>{t('可操作的设计解读','INTERACTIVE DESIGN EXPLANATION',lang)}</span><h3>{title}</h3><p>{desc}</p></header><div class="demo-body">{body}</div><p class="demo-provenance">{t('为本作品集重新制作的交互解读，基于原设计逻辑；不代表当时已上线的产品。','Recreated for this portfolio from the original design logic; this is not a claim of a shipped product.',lang)}</p><noscript><p>{t('启用 JavaScript 即可操作；下方仍可查看原始设计证据。','Enable JavaScript to try this explanation. Original design evidence remains available below.',lang)}</p></noscript></div>'''

def studio(lang):
 required=t('必选','Required',lang);optional=t('可选','Optional',lang)
 body=f'''<div class="studio-toolbar"><span>Studio / {t('配方编辑器','Recipe editor',lang)}</span><button class="demo-link" type="button" data-action="reset">{t('重置','Reset',lang)} ↺</button></div><div class="recipe-canvas"><fieldset class="recipe-inputs"><legend>{t('01 输入 · 勾选以连接规则','01 INPUTS · Check to connect',lang)}</legend><label class="recipe-node"><input type="checkbox" name="gamepad" checked><span><b>Gamepad</b><small>{required} · {t('基础值','Base value',lang)} 20</small></span><span class="node-port" aria-hidden="true"></span></label><label class="recipe-node"><input type="checkbox" name="battery" checked><span><b>Normal Battery</b><small>{required} · {t('电池贡献','Battery contribution',lang)} 30</small></span><span class="node-port" aria-hidden="true"></span></label><label class="recipe-node optional-node"><input type="checkbox" name="charger"><span><b>Super Charger</b><small>{optional} · {t('电池贡献 × 2','Battery contribution × 2',lang)}</small></span><span class="node-port" aria-hidden="true"></span></label></fieldset><div class="recipe-connector" aria-hidden="true">→</div><div class="recipe-output"><span class="demo-label">02 {t('输出属性','OUTPUT ATTRIBUTE',lang)}</span><b>Battery Life</b><output data-result="value">50</output><code data-result="formula">20 + 30 = 50</code><p data-result="explanation" role="status">{t('普通电池贡献 30。加入 Super Charger，看看同一条规则如何变化。','Normal Battery contributes 30. Add Super Charger to see the same rule change.',lang)}</p></div></div><p class="demo-footnote">{t('20 与 30 是演示数值，仅用于说明确定性规则，不是原项目的实际参数。','20 and 30 are illustrative values for this deterministic rule, not the original project’s actual parameters.',lang)}</p><a class="demo-next" href="#app-demo">{t('继续到 App，体验确认与消耗','Continue to the App: confirmation and consumption',lang)} ↓</a>'''
 return shell('studio',t('亲手连接一次输入与输出。','Connect the inputs to the outcome.',lang),t('切换材料，查看必选、可选与属性计算如何保持一致。','Toggle materials to trace required inputs, optional inputs and the attribute calculation.',lang),body,lang)

def craft(lang):
 body=f'''<div class="craft-layout"><div class="craft-inventory"><span class="demo-label">APP / {t('示例背包','SAMPLE INVENTORY',lang)}</span><h4>{t('合成前，先看清代价。','See the cost before crafting.',lang)}</h4><dl><div><dt>Gamepad</dt><dd data-count="gamepad">1</dd></div><div><dt>Normal Battery</dt><dd data-count="battery">0</dd></div><div><dt>{t('合成物品','Crafted item',lang)}</dt><dd data-count="crafted">0</dd></div></dl><p class="demo-footnote">{t('示例只保留必选材料。所有变化只发生在本页，重置可重新开始。','This example uses the required materials only. Changes stay on this page; reset starts again.',lang)}</p></div><div class="craft-flow"><ol class="state-track" aria-label="{t('合成步骤','Crafting stages',lang)}">{''.join(f'<li data-stage="{key}">{label}</li>' for key,label in [('missing',t('材料','Materials',lang)),('ready',t('就绪','Ready',lang)),('confirm',t('确认','Confirm',lang)),('complete',t('完成','Complete',lang))])}</ol><div class="craft-status" role="status" tabindex="-1"><h4 data-status-title>{t('还缺一块电池','One battery is missing',lang)}</h4><p data-status-copy>{t('配方需要 1 个 Gamepad 与 1 个 Normal Battery。先补齐示例材料。','The recipe needs 1 Gamepad and 1 Normal Battery. Add the missing sample material first.',lang)}</p></div><div class="confirmation-summary" data-confirmation hidden><span>{t('本次消耗','YOU WILL SPEND',lang)}</span><b>1 × Gamepad ＋ 1 × Normal Battery</b><span>{t('本次获得','YOU WILL RECEIVE',lang)}</span><b>1 × {t('合成物品','Crafted item',lang)} · Battery Life 50</b></div><div class="demo-actions"><button type="button" class="demo-button" data-action="collect">{t('加入示例电池','Add sample battery',lang)}</button><button type="button" class="demo-button" data-action="open" hidden>{t('查看合成确认','Review craft',lang)}</button><button type="button" class="demo-button" data-action="confirm" hidden>{t('确认消耗并合成','Confirm & craft',lang)}</button><button type="button" class="demo-button secondary" data-action="cancel" hidden>{t('取消，保留材料','Cancel, keep materials',lang)}</button><button type="button" class="demo-link" data-action="reset">{t('重新体验','Start again',lang)} ↺</button></div></div></div>'''
 return shell('craft',t('从材料不足，到知情确认。','From missing materials to informed confirmation.',lang),t('补齐材料、检查消耗，再确认。也可以取消，材料会留在背包中。','Add a material, review the cost, then confirm. Cancelling keeps the inventory intact.',lang),body,lang,'app-demo')

def journey(lang):
 body=f'''<ol class="journey-track" aria-label="{t('体验阶段','Journey stages',lang)}"><li data-stage="before">01 {t('骑行前','Before',lang)}</li><li data-stage="during">02 {t('骑行中','During',lang)}</li><li data-stage="after">03 {t('骑行后','After',lang)}</li></ol><div class="journey-content"><div class="journey-map" aria-hidden="true"><div class="map-grid"></div><div class="map-route"></div><span class="map-point point-start">01</span><span class="map-point point-pause">02</span><span class="map-point point-end">03</span><span class="map-caption">{t('示意路线 · 非真实地图','CONCEPT ROUTE · NOT A REAL MAP',lang)}</span></div><div class="journey-panel"><div class="journey-status" role="status" tabindex="-1"><span class="demo-label" data-journey-label>{t('从兴趣开始','START WITH AN INTEREST',lang)}</span><h4 data-journey-title>{t('今天，想看点什么？','What would you like to explore?',lang)}</h4><p data-journey-copy>{t('先选择一条示例路线，再体验沿途记录和骑行回顾。','Choose a sample route, then explore a stop and the post-ride memory.',lang)}</p></div><fieldset class="route-options"><legend>{t('选择示例路线','Choose a sample route',lang)}</legend><label><input type="radio" name="route" value="greenway"><span><b>{t('绿道小风景','Greenway discoveries',lang)}</b><small>{t('公园 → 河边停留','Park → Riverside stop',lang)}</small></span></label><label><input type="radio" name="route" value="city"><span><b>{t('和朋友逛街角','Neighbourhood with friends',lang)}</b><small>{t('街区 → 咖啡店停留','Neighbourhood → Café stop',lang)}</small></span></label></fieldset><div class="memory-card" data-memory hidden><small>{t('这次骑行留下了','A MEMORY FROM THIS RIDE',lang)}</small><b data-memory-title></b><p data-memory-copy></p></div><div class="demo-actions"><button type="button" class="demo-button" data-action="start" disabled>{t('开始示例旅程','Start sample journey',lang)}</button><button type="button" class="demo-button secondary" data-action="save" hidden>{t('记下这次停留','Save this stop',lang)}</button><button type="button" class="demo-button" data-action="finish" hidden>{t('进入骑行后回顾','See post-ride recap',lang)}</button><button type="button" class="demo-link" data-action="reset">{t('重选路线','Start again',lang)} ↺</button></div></div></div><p class="demo-footnote">{t('这是用户旅程的交互说明，不使用定位，不开启真实骑行，也不发放实际奖励。','This explains the user journey. It uses no location data, starts no real ride and grants no actual rewards.',lang)}</p>'''
 return shell('journey',t('沿着一次骑行，试试三个设计机会。','Try three opportunities along one ride.',lang),t('把路线选择、沿途停留、记录与奖励放回同一段体验。','Connect route choice, a pause, memories and rewards within one experience.',lang),body,lang)

def table(lang):
 body=f'''<div class="table-workspace" data-theme="day"><div class="table-toolbar"><div><span class="demo-label">SMT / {t('示例账户','SAMPLE ACCOUNT',lang)}</span><h4>{t('账户持仓','Account positions',lang)}</h4></div><button type="button" class="demo-button secondary" data-action="theme" aria-pressed="false">{t('夜间主题','Night theme',lang)}</button></div><form class="table-query"><label for="position-query">{t('查询示例名称或代码','Find a sample name or code',lang)}</label><div><input id="position-query" name="query" type="search" placeholder="{t('例如：示例甲 / DEMO-A','e.g. Sample Alpha / DEMO-A',lang)}" autocomplete="off"><button class="demo-button" type="submit">{t('查询','Query',lang)}</button></div></form><div class="state-controls" role="group" aria-label="{t('预览表格状态','Preview table states',lang)}"><button type="button" data-table-state="default" aria-pressed="true">{t('默认','Default',lang)}</button><button type="button" data-table-state="selected" aria-pressed="false">{t('选中','Selected',lang)}</button><button type="button" data-table-state="hover" aria-pressed="false">{t('悬停 / 聚焦','Hover / Focus',lang)}</button><button type="button" data-table-state="empty" aria-pressed="false">{t('无数据','No data',lang)}</button></div><div class="table-scroll" role="region" aria-label="{t('示例持仓表格，可横向滚动','Sample positions table; scroll horizontally',lang)}" tabindex="0"><table class="positions-table"><caption>{t('虚构示例数据 · 仅展示组件状态','Fictional sample data · Component states only',lang)}</caption><thead><tr><th scope="col">{t('选择','Select',lang)}</th><th scope="col">{t('名称 / 代码','Name / Code',lang)}</th><th scope="col">{t('数量','Quantity',lang)}</th><th scope="col">{t('示例估值','Sample value',lang)}</th></tr></thead><tbody data-table-rows></tbody></table></div><div class="table-footer"><p data-table-status role="status"></p><button class="demo-link" type="button" data-action="clear">{t('清除查询与选择','Clear query & selection',lang)}</button></div></div><p class="demo-footnote">{t('本页不连接账户或行情，不提供交易操作。历史交付范围为组件、规范与维护；这里的代码是作品集解读。','No accounts, market feed or trading actions are connected. The historical delivery was components, guidelines and maintenance; this code is a portfolio explanation.',lang)}</p>'''
 return shell('table',t('让状态变化，保持阅读位置。','Change the state, keep the reading structure.',lang),t('查询、选中一行，或切换明暗主题。每个状态沿用同一套信息结构。','Query, select a row or switch theme. Each state keeps the same information structure.',lang),body,lang)

def fridge(lang):
 body=f'''<div class="fridge-layout"><fieldset class="fridge-items"><legend>{t('选择一个示例物品','Choose a sample item',lang)}</legend><label><input type="radio" name="fridge-item" value="unknown" checked><span><small>{t('上层 · 未认领','TOP SHELF · UNCLAIMED',lang)}</small><b>{t('透明餐盒','Clear container',lang)}</b></span></label><label><input type="radio" name="fridge-item" value="own"><span><small>{t('中层 · 我的','MIDDLE SHELF · MINE',lang)}</small><b>{t('蓝色午餐盒','Blue lunch box',lang)}</b></span></label><label><input type="radio" name="fridge-item" value="other"><span><small>{t('冰箱门 · 室友的','DOOR · HOUSEMATE’S',lang)}</small><b>{t('玻璃瓶','Glass bottle',lang)}</b></span></label><p class="demo-footnote">{t('未认领表示归属未知，不等于可自由处置。','Unclaimed means ownership is unknown; it does not give permission to act.',lang)}</p></fieldset><div class="fridge-detail"><dl class="permission-facts"><div><dt>{t('位置','Location',lang)}</dt><dd data-fridge-location></dd></div><div><dt>{t('归属','Ownership',lang)}</dt><dd data-fridge-owner></dd></div><div><dt>{t('处理权限','Permission',lang)}</dt><dd data-fridge-permission></dd></div></dl><div class="fridge-status" role="status" tabindex="-1"><h4 data-fridge-title></h4><p data-fridge-copy></p></div><div class="demo-actions"><button type="button" class="demo-button" data-action="claim">{t('这是我的物品','This item is mine',lang)}</button><button type="button" class="demo-button" data-action="confirmClaim" hidden>{t('确认归属声明','Confirm ownership declaration',lang)}</button><button type="button" class="demo-button" data-action="ask" hidden>{t('预览询问主人','Preview asking the owner',lang)}</button><button type="button" class="demo-button" data-action="plan" hidden>{t('记录我的计划','Record my plan',lang)}</button><button type="button" class="demo-button" data-action="savePlan" hidden>{t('保存“稍后自行查看”','Save “I’ll check it later”',lang)}</button><button type="button" class="demo-button secondary" data-action="cancel" hidden>{t('取消','Cancel',lang)}</button><button type="button" class="demo-link" data-action="reset">{t('重置示例','Reset example',lang)} ↺</button></div></div></div><p class="demo-footnote">{t('示例只保存在当前页面，不会发送消息或同步给室友。界面不判断食物安全。','This example stays on this page. It sends no messages and does not sync with housemates. The interface does not determine food safety.',lang)}</p>'''
 return shell('fridge',t('看得见，不等于有权处理。','Visibility is not permission.',lang),t('换一个物品，看看位置、归属和可执行动作如何分别变化。','Switch items to see how location, ownership and available actions differ.',lang),body,lang)

DEMO_SECTIONS={('qingju',3):journey,('playbook',2):studio,('playbook',3):craft,('smt',3):table,('commons-fridge',3):fridge}

def section_demo(slug,number,lang):
 factory=DEMO_SECTIONS.get((slug,number))
 return factory(lang) if factory else ''

def motion_demos(lang):
 clips=[('recipe',t('配方编辑','Recipe editor',lang),t('观看输入、规则与输出如何在原始画布中连接。','See inputs, rules and outputs connect on the original canvas.',lang)),('items',t('物品交互','Item interaction',lang),t('查看原始物品相关流程中的界面操作与状态反馈。','Watch interface actions and state feedback in the original item flow.',lang)),('comments',t('评论交互','Comment interaction',lang),t('查看原始评论相关流程的操作与反馈。','Watch actions and feedback in the original comment flow.',lang))]
 return f'''<div class="original-motion" data-motion><div class="demo-eyebrow">{t('原始动态演示','ORIGINAL MOTION DEMOS',lang)}</div><h3>{t('也看看当时的交互。','See the interaction as it was.',lang)}</h3><p>{t('作品集中的原始演示记录，包含我使用 ProtoPie 制作的交互演示。与上方可直接操作的网页重建区分呈现。','Original recordings from my portfolio, including interaction work made with ProtoPie. Presented separately from the interactive browser reconstruction above.',lang)}</p><div class="motion-tabs" role="group" aria-label="{t('选择原始演示','Choose an original demo',lang)}">{''.join(f'<button type="button" data-clip="{key}" aria-pressed="{str(n==0).lower()}">{label}</button>' for n,(key,label,desc) in enumerate(clips))}</div>{''.join(f'<figure data-clip-panel="{key}" {"hidden" if n else ""}><video controls playsinline preload="none" poster="/assets/motion/{key}-poster.webp" aria-label="{label}"><source src="/assets/motion/{key}.mp4" type="video/mp4"></video><figcaption>{desc} {t("无声录屏。","Silent recording.",lang)}</figcaption></figure>' for n,(key,label,desc) in enumerate(clips))}</div>'''
